int main(int argc, char **argv) {
    if (argc < 2) { fprintf(stderr, "usage: minicc <file.mini>\n"); return 1; }
    char *source = read_file(argv[1]);
    if (!source) return 1;

    Lexer lex;
    lexer_init(&lex, source);
    if (lexer_tokenize(&lex) < 0) { free(source); return 1; }

    Parser parser;
    parser_init(&parser, lex.tokens, lex.token_count);
    ASTNode *program = parse_program(&parser);
    if (parser.had_error) { free(source); ast_free_all(); return 1; }

    Compiler compiler;
    compiler_init(&compiler);
    if (compile(&compiler, program) < 0) { free(source); ast_free_all(); return 1; }

    VM vm;
    vm_init(&vm, &compiler);
    int result = vm_run(&vm);

    free(source);
    ast_free_all();
    return result;
}
